CREATE TABLE regions (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL
);
CREATE TABLE customers (
  id INTEGER PRIMARY KEY,
  region_id INTEGER REFERENCES regions(id),
  name TEXT NOT NULL
);
CREATE TABLE orders (
  id INTEGER PRIMARY KEY,
  customer_id INTEGER REFERENCES customers(id),
  amount REAL,
  status TEXT NOT NULL
);

